extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var elena_data = load("res://story/elena.tres")
	if not check("elena_tres", elena_data != null, "La risorsa res://story/elena.tres deve caricarsi correttamente"):
		return
	var display_name: String = get_prop(elena_data, "display_name", "")
	check("elena_name", display_name == "Elena", "Il display_name della risorsa deve essere 'Elena'")
	var exprs: Dictionary = get_prop(elena_data, "expressions", {})
	check("elena_expr", exprs.has("neutral"), "La risorsa elena.tres deve contenere l'espressione 'neutral'")

	var display := await instantiate_scene("res://story/character_display.tscn")
	if not check("display_scene", display != null, "La scena character_display.tscn deve essere istanziabile"):
		return

	check("setup", has_function(display, "setup"), "CharacterDisplay deve contenere il metodo setup")
	check("focus", has_function(display, "set_focused"), "CharacterDisplay deve contenere il metodo set_focused")
	check("move", has_function(display, "move_to"), "CharacterDisplay deve contenere il metodo move_to")
	check("fade_in", has_function(display, "fade_in"), "CharacterDisplay deve contenere il metodo fade_in")
	check("fade_out", has_function(display, "fade_out"), "CharacterDisplay deve contenere il metodo fade_out")

	call_if_exists(display, "setup", [elena_data])
	check("texture_set", get_prop(display, "texture", null) != null, "Dopo setup, la texture del display deve essere impostata")

